"use client";

import type { Course } from "@/app/data/courses";
import {
  IconCalendar,
  IconClock,
  IconUsers,
  IconArrowRight,
} from "@tabler/icons-react";

const levelColors: Record<string, string> = {
  A1: "bg-success/30 text-success",
  A2: "bg-pistachio/30 text-pistachio",
  B1: "bg-sage/30 text-sage",
  B2: "bg-accent/30 text-accent",
  C1: "bg-ballet-slipper/30 text-ballet-slipper",
  C2: "bg-bubblegum/30 text-bubblegum",
};

interface CourseCardProps {
  course: Course;
  onSelect: (course: Course) => void;
}

export default function CourseCard({ course, onSelect }: CourseCardProps) {
  const startDate = new Date(course.startDate).toLocaleDateString("de-DE", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  return (
    <button
      type="button"
      onClick={() => onSelect(course)}
      className="group flex flex-col overflow-hidden rounded-2xl border border-background/10 bg-sapphire text-left shadow-sm transition-all hover:shadow-lg hover:-translate-y-1"
    >
      {/* Image */}
      <div className="relative h-48 w-full overflow-hidden">
        <img
          src={course.image}
          alt={course.title}
          className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
        />
        {/* Level badge */}
        <span
          className={`absolute top-3 left-3 rounded-full px-3 py-1 text-xs font-bold ${levelColors[course.level]}`}
        >
          {course.level}
        </span>
      </div>

      {/* Content */}
      <div className="flex flex-1 flex-col gap-3 p-5">
        <h3 className="text-lg font-bold text-background">{course.title}</h3>
        <p className="text-sm text-balance/50 line-clamp-2">
          {course.description}
        </p>

        {/* Schedule */}
        <div className="flex flex-col gap-1.5 text-sm text-balance/70">
          <div className="flex items-center gap-2">
            <IconClock size={15} className="text-primary" />
            <span>
              {course.schedule.days}, {course.schedule.time}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <IconCalendar size={15} className="text-primary" />
            <span>Ab {startDate}</span>
          </div>
        </div>

        {/* Footer */}
        <div className="mt-auto flex items-center justify-between border-t border-background/5 pt-3">
          <div className="flex items-center font-semibold gap-1.5 text-sm text-balance/50">
            <IconUsers size={15} />
            <span>
              {course.enrolled}/{course.maxCapacity}
            </span>
          </div>
          <span className="text-lg font-bold text-background">
            {course.price}
          </span>
        </div>

        {/* CTA hint */}
        <div className="flex items-center gap-1 text-sm font-bold text-bubblegum transition-transform hover:underline ">
          View details
          <IconArrowRight
            size={14}
            className="transition-transform group-hover:translate-x-1"
          />
        </div>
      </div>
    </button>
  );
}

"use client";

import type { Course } from "@/app/data/courses";
import {
  IconCalendar,
  IconClock,
  IconUsers,
  IconArrowRight,
} from "@tabler/icons-react";

const levelColors: Record<string, string> = {
  A1: "bg-success/20 text-success",
  A2: "bg-pistachio/20 text-pistachio",
  B1: "bg-sage/20 text-sage",
  B2: "bg-accent/20 text-accent",
  C1: "bg-ballet-slipper/20 text-ballet-slipper",
  C2: "bg-bubblegum/20 text-bubblegum",
};

interface CourseCardProps {
  course: Course;
  onSelect: (course: Course) => void;
}

export default function CourseCard({ course, onSelect }: CourseCardProps) {
  const startDate = new Date(course.startDate).toLocaleDateString("de-DE", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  return (
    <button
      type="button"
      onClick={() => onSelect(course)}
      className="group flex flex-col overflow-hidden rounded-2xl border border-foreground/10 bg-background text-left shadow-sm transition-all hover:shadow-lg hover:-translate-y-1"
    >
      {/* Image */}
      <div className="relative h-48 w-full overflow-hidden">
        <img
          src={course.image}
          alt={course.title}
          className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
        />
        {/* Level badge */}
        <span
          className={`absolute top-3 left-3 rounded-full px-3 py-1 text-xs font-bold ${levelColors[course.level]}`}
        >
          {course.level}
        </span>
      </div>

      {/* Content */}
      <div className="flex flex-1 flex-col gap-3 p-5">
        <h3 className="text-lg font-bold text-foreground">{course.title}</h3>
        <p className="text-sm text-foreground/50 line-clamp-2">
          {course.description}
        </p>

        {/* Schedule */}
        <div className="flex flex-col gap-1.5 text-sm text-foreground/60">
          <div className="flex items-center gap-2">
            <IconClock size={15} className="text-primary" />
            <span>
              {course.schedule.days}, {course.schedule.time}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <IconCalendar size={15} className="text-primary" />
            <span>Ab {startDate}</span>
          </div>
        </div>

        {/* Footer */}
        <div className="mt-auto flex items-center justify-between border-t border-foreground/5 pt-3">
          <div className="flex items-center gap-1.5 text-sm text-foreground/50">
            <IconUsers size={15} />
            <span>
              {course.enrolled}/{course.maxCapacity}
            </span>
          </div>
          <span className="text-lg font-bold text-foreground">
            {course.price}
          </span>
        </div>

        {/* CTA hint */}
        <div className="flex items-center gap-1 text-sm font-semibold text-accent transition-colors group-hover:text-ballet-slipper">
          View details
          <IconArrowRight
            size={14}
            className="transition-transform group-hover:translate-x-1"
          />
        </div>
      </div>
    </button>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { IconArrowRight } from "@tabler/icons-react";
import { courses } from "@/app/data/courses";
import type { Course } from "@/app/data/courses";
import CourseCard from "@/app/components/CourseCard";
import CourseDetailModal from "@/app/components/CourseDetailModal";

export default function FeaturedCourses() {
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const featured = courses.slice(0, 3);

  return (
    <>
      <section className="relative mx-auto max-w-7xl py-24 mt-30">
        {/* Header */}
        <div className="mb-12 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <p className="text-sm font-semibold uppercase tracking-wider text-accent">
              Our Courses
            </p>
            <h2 className="mt-2 text-3xl font-bold text-foreground md:text-4xl">
              Start learning German today
            </h2>
            <p className="mt-3 max-w-lg text-base text-foreground/50">
              From beginner to proficiency — pick the level that matches your
              goals and join a class that fits your schedule.
            </p>
          </div>
          <Link
            href="/courses"
            className="flex items-center gap-1.5 text-sm font-semibold text-accent transition-colors hover:text-ballet-slipper"
          >
            View all courses
            <IconArrowRight size={16} />
          </Link>
        </div>

        {/* Cards grid */}
        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {featured.map((course) => (
            <CourseCard
              key={course.id}
              course={course}
              onSelect={setSelectedCourse}
            />
          ))}
        </div>
      </section>

      <CourseDetailModal
        course={selectedCourse}
        onClose={() => setSelectedCourse(null)}
      />
    </>
  );
}

